from pathlib import Path

root=Path('/mnt/data/diag')

# Patch streamAddons.js
p=root/'src/lib/streamAddons.js'
s=p.read_text()

# Replace rankStreams function
old='''function rankStreams(streams) {\n  return [...streams].sort((a, b) => {\n    const provider = (b.addonPriority || 0) - (a.addonPriority || 0)\n    if (provider) return provider\n    const quality = (b.quality || 0) - (a.quality || 0)\n    if (quality) return quality\n    const hls = Number(b.kind === 'hls') - Number(a.kind === 'hls')\n    if (hls) return hls\n    return a.addonName.localeCompare(b.addonName)\n  })\n}\n'''
new='''function rankStreams(streams) {\n  const qualityPreference = (quality) => {\n    if (quality === 1080) return 100\n    if (quality === 720) return 90\n    if (quality === 1440) return 85\n    if (quality === 2160) return 80\n    if (quality === 576) return 70\n    if (quality === 480) return 60\n    return 50\n  }\n\n  return [...streams].sort((a, b) => {\n    const provider = (b.addonPriority || 0) - (a.addonPriority || 0)\n    if (provider) return provider\n\n    const match = (b.matchScore || 0) - (a.matchScore || 0)\n    if (match) return match\n\n    const quality = qualityPreference(b.quality) - qualityPreference(a.quality)\n    if (quality) return quality\n\n    const hls = Number(b.kind === 'hls') - Number(a.kind === 'hls')\n    if (hls) return hls\n    return a.addonName.localeCompare(b.addonName)\n  })\n}\n'''
if old not in s: raise SystemExit('rankStreams block not found')
s=s.replace(old,new)

# Insert matching helpers before normalizeStream
marker='''function detectKind(stream) {\n'''
idx=s.index(marker)
# We'll insert helper after detectKind block by finding normalizeStream marker
normalize_marker='''export function normalizeStream(stream, addon, index = 0) {\n'''
idx2=s.index(normalize_marker)
helpers='''function normalizeMatchText(value) {\n  return String(value || '')\n    .toLowerCase()\n    .replace(/\\[[^\\]]*\\]/g, ' ')\n    .replace(/[^a-z0-9]+/g, ' ')\n    .replace(/\\s+/g, ' ')\n    .trim()\n}\n\nfunction titleTokens(value) {\n  return normalizeMatchText(value)\n    .split(' ')\n    .filter((token) => token.length >= 3 && !['the', 'and', 'for', 'with', 'from'].includes(token))\n}\n\nfunction scoreStreamMatch(stream, expectedTitle, expectedYear, type, season, episode) {\n  const sourceText = normalizeMatchText(`${stream?.title || ''} ${stream?.name || ''} ${stream?.behaviorHints?.filename || ''}`)\n  const tokens = titleTokens(expectedTitle)\n  if (!sourceText || !tokens.length) return 0.5\n\n  const matched = tokens.filter((token) => sourceText.includes(token)).length\n  let score = matched / tokens.length\n\n  if (expectedYear) {\n    const yearText = String(expectedYear)\n    if (sourceText.includes(yearText)) score += 0.15\n    else if (/\\b(?:19|20)\\d{2}\\b/.test(sourceText)) score -= 0.1\n  }\n\n  if (type === 'series' && season && episode) {\n    const paddedSeason = String(season).padStart(2, '0')\n    const paddedEpisode = String(episode).padStart(2, '0')\n    const seasonEpisodeMatch =\n      sourceText.includes(`s${paddedSeason}e${paddedEpisode}`) ||\n      sourceText.includes(`s${season}e${episode}`)\n    if (seasonEpisodeMatch) score += 0.2\n    const episodeMarkers = [\n      `episode ${episode}`,\n      `ep ${episode}`,\n      `episode${episode}`,\n      `e${paddedEpisode}`,\n    ]\n    if (episodeMarkers.some((marker) => sourceText.includes(marker))) score += 0.1\n  }\n\n  return Math.max(0, Math.min(1, score))\n}\n\n'''
s=s[:idx2]+helpers+s[idx2:]

# Replace normalizeStream signature and add fields
s=s.replace('export function normalizeStream(stream, addon, index = 0) {', 'export function normalizeStream(stream, addon, index = 0, context = {}) {')
old2='''  return {\n    id: `${addon.id}-${index}-${encodeURIComponent(url || title)}`,\n    addonId: addon.id,\n    addonName: addon.name,\n    addonPriority: Number(addon.priority) || 0,\n    title,\n    url,\n    kind,\n    quality: normalizeQuality(`${title} ${stream?.quality || ''}`),\n    subtitles: Array.isArray(stream?.subtitles) ? stream.subtitles : [],\n    externalUrl: String(stream?.externalUrl || ''),\n    infoHash: String(stream?.infoHash || ''),\n    fileIdx: stream?.fileIdx,\n    behaviorHints,\n    notWebReady: Boolean(behaviorHints.notWebReady),\n    browserCandidate: /^https?:\\/\\//i.test(url) && (kind === 'http' || kind === 'hls'),\n  }\n}\n'''
new2='''  const quality = normalizeQuality(`${title} ${stream?.quality || ''}`)\n  const matchScore = scoreStreamMatch(\n    stream,\n    context.expectedTitle,\n    context.expectedYear,\n    context.type,\n    context.season,\n    context.episode,\n  )\n\n  return {\n    id: `${addon.id}-${index}-${encodeURIComponent(url || title)}`,\n    addonId: addon.id,\n    addonName: addon.name,\n    addonPriority: Number(addon.priority) || 0,\n    title,\n    url,\n    kind,\n    quality,\n    matchScore,\n    subtitles: Array.isArray(stream?.subtitles) ? stream.subtitles : [],\n    externalUrl: String(stream?.externalUrl || ''),\n    infoHash: String(stream?.infoHash || ''),\n    fileIdx: stream?.fileIdx,\n    behaviorHints,\n    notWebReady: Boolean(behaviorHints.notWebReady),\n    browserCandidate: /^https?:\\/\\//i.test(url) && (kind === 'http' || kind === 'hls'),\n  }\n}\n'''
if old2 not in s: raise SystemExit('normalizeStream block not found')
s=s.replace(old2,new2)

# Update fetchAddonStreams signature and call normalizeStream
s=s.replace('export async function fetchAddonStreams(addon, type, ids, timeoutMs = 7000) {', 'export async function fetchAddonStreams(addon, type, ids, timeoutMs = 7000, context = {}) {')
s=s.replace('''        .map((stream, index) => normalizeStream(stream, addon, index))''', '''        .map((stream, index) => normalizeStream(stream, addon, index, context))''')

# Update progressive signature and call
s=s.replace('export async function findPlayableStreamsProgressive({ addons, type, ids, onUpdate }) {', 'export async function findPlayableStreamsProgressive({ addons, type, ids, context = {}, onUpdate }) {')
s=s.replace('const streams = await fetchAddonStreams(addon, type, ids)', 'const streams = await fetchAddonStreams(addon, type, ids, 7000, context)')
# Dedup only by URL if present already. Keep.
p.write_text(s)

# Patch StreamPage
p=root/'src/pages/StreamPage.jsx'
s=p.read_text()
s=s.replace("const PRIORITY_GRACE_MS = 1100", "const PRIORITY_GRACE_MS = 450")
# Add timer ref
s=s.replace("  const searchRequestRef = useRef(0)\n", "  const searchRequestRef = useRef(0)\n  const priorityTimerRef = useRef(null)\n")
# Replace loadSources function block wholesale via markers
start=s.index('  const loadSources = useCallback(async () => {')
end=s.index('\n  useEffect(() => {\n    loadSources()\n  }, [loadSources])', start)
new_load='''  const loadSources = useCallback(async () => {\n    if (!item?.tmdb_id) return\n    const requestId = ++searchRequestRef.current\n    if (priorityTimerRef.current) window.clearTimeout(priorityTimerRef.current)\n    setSearchComplete(false)\n    setAutoStart(false)\n    setStreams([])\n    setSubtitles([])\n    searchStartedAtRef.current = Date.now()\n\n    const addons = getStreamAddons()\n    const baseIds = { imdbId: '', tmdbId: item.tmdb_id }\n    const context = {\n      expectedTitle: item.title,\n      expectedYear: item.year,\n      type: item.type,\n      season: item.type === 'series' ? selection.season : undefined,\n      episode: item.type === 'series' ? selection.episode : undefined,\n    }\n\n    let allStreams = []\n    let completedRuns = 0\n    let latestResult = null\n\n    const update = (result) => {\n      if (requestId !== searchRequestRef.current) return\n      latestResult = result\n      allStreams = result.playable\n      setStreams(result.playable)\n      if (result.playable.length && !autoStart) {\n        const hasPengu = result.playable.some((source) => source.addonId === 'penguplay')\n        const elapsed = Date.now() - searchStartedAtRef.current\n        if (hasPengu || elapsed >= PRIORITY_GRACE_MS || result.complete) {\n          setAutoStart(true)\n        } else if (!priorityTimerRef.current) {\n          priorityTimerRef.current = window.setTimeout(() => {\n            priorityTimerRef.current = null\n            if (requestId !== searchRequestRef.current) return\n            setAutoStart(true)\n          }, Math.max(0, PRIORITY_GRACE_MS - elapsed))\n        }\n      }\n      if (result.complete && completedRuns >= 1) setSearchComplete(true)\n    }\n\n    // Start a fast TMDB-ID search immediately. This makes first-run playback possible\n    // while the IMDb lookup is still in flight.\n    const firstRun = findPlayableStreamsProgressive({\n      addons,\n      type: item.type,\n      ids: baseIds,\n      context,\n      onUpdate: update,\n    })\n\n    // Resolve IMDb in parallel rather than making source discovery wait for it.\n    const idsPromise = getExternalIds(item.tmdb_id, item.type)\n\n    const subtitleVideoId = item.type === 'series'\n      ? `tmdb:${item.tmdb_id}:${selection.season}:${selection.episode}`\n      : `tmdb:${item.tmdb_id}`\n    findSubtitles({ type: item.type, videoId: subtitleVideoId })\n      .then((result) => {\n        if (requestId === searchRequestRef.current) setSubtitles(result.tracks || [])\n      })\n      .catch(() => null)\n\n    try {\n      const ids = await idsPromise\n      if (requestId !== searchRequestRef.current) return\n\n      const imdbVideoId = ids.imdb_id\n        ? (item.type === 'series'\n          ? `${ids.imdb_id}:${selection.season}:${selection.episode}`\n          : ids.imdb_id)\n        : ''\n\n      if (imdbVideoId) {\n        // Query the canonical IMDb ID in parallel with the initial TMDB-ID pass.\n        const imdbResult = await findPlayableStreamsProgressive({\n          addons,\n          type: item.type,\n          ids: { imdbId: imdbVideoId, tmdbId: ids.tmdb_id },\n          context,\n          onUpdate: (result) => {\n            if (requestId !== searchRequestRef.current) return\n            completedRuns = result.complete ? completedRuns + 1 : completedRuns\n            update(result)\n          },\n        })\n        if (requestId !== searchRequestRef.current) return\n        latestResult = imdbResult\n      }\n\n      const tmdbResult = await firstRun\n      if (requestId !== searchRequestRef.current) return\n      latestResult = tmdbResult\n\n      // Merge the two passes so a source found under either identifier is available.\n      const merged = [...(imdbResultOrEmpty(latestResult) || []), ...(tmdbResult.playable || [])]\n      const unique = [...new Map(merged.filter((source) => source?.url).map((source) => [source.url, source])).values()]\n        .sort((a, b) => ((b.addonPriority || 0) - (a.addonPriority || 0)) || ((b.matchScore || 0) - (a.matchScore || 0)) || ((b.quality || 0) - (a.quality || 0)))\n      setStreams(unique)\n      setSearchComplete(true)\n      if (unique.length) setAutoStart(true)\n    } catch (error) {\n      const tmdbResult = await firstRun.catch(() => null)\n      if (requestId !== searchRequestRef.current) return\n      if (tmdbResult?.playable?.length) {\n        setStreams(tmdbResult.playable)\n        setAutoStart(true)\n      }\n      setSearchComplete(true)\n      if (!tmdbResult?.playable?.length) notify?.(error.message || 'Unable To Find Streaming Sources.', 'error')\n    } finally {\n      if (requestId === searchRequestRef.current) {\n        setSearchComplete(true)\n      }\n    }\n\n    function imdbResultOrEmpty(result) {\n      return result?.playable || []\n    }\n  }, [item, notify, selection.episode, selection.season])\n'''
s=s[:start]+new_load+s[end:]
# reset autoStart bug: use state stale in update. We'll patch with functional set or ref? easier later.
# Remove duplicate tmdb result race issue by simpler patch will be revisited.
# Add cleanup timer effect before item guard perhaps.
s=s.replace("  useEffect(() => {\n    loadSources()\n  }, [loadSources])\n", "  useEffect(() => {\n    loadSources()\n    return () => {\n      if (priorityTimerRef.current) window.clearTimeout(priorityTimerRef.current)\n    }\n  }, [loadSources])\n")
# Pass playbackKey to player
s=s.replace('<StreamPlayer streams={streams} subtitleTracks={subtitles} discoveryComplete={searchComplete} autoStart={autoStart} onSuccess={() => null}', '<StreamPlayer playbackKey={`${item.id}:${selection.season}:${selection.episode}`} streams={streams} subtitleTracks={subtitles} discoveryComplete={searchComplete} autoStart={autoStart} onSuccess={() => null}')
p.write_text(s)

# Patch StreamPlayer
p=root/'src/components/StreamPlayer.jsx'
s=p.read_text()
s=s.replace("export default function StreamPlayer({ streams = [], subtitleTracks = [], discoveryComplete = false, autoStart = false, onSuccess, onAllFailed }) {", "export default function StreamPlayer({ playbackKey = '', streams = [], subtitleTracks = [], discoveryComplete = false, autoStart = false, onSuccess, onAllFailed }) {")
# Replace subtitle cleanup effect
old_sub='''  useEffect(() => {\n    let active = true\n    Promise.all((subtitleTracks || []).slice(0, 8).map(subtitleSource)).then((tracks) => {\n      if (active) setPreparedSubtitles(tracks.filter((track) => track?.src))\n    })\n    return () => {\n      active = false\n      preparedSubtitles.forEach((track) => track.revoke?.())\n    }\n  }, [subtitleTracks])\n'''
new_sub='''  useEffect(() => {\n    let active = true\n    let createdTracks = []\n    Promise.all((subtitleTracks || []).slice(0, 8).map(subtitleSource)).then((tracks) => {\n      createdTracks = tracks.filter((track) => track?.src)\n      if (active) setPreparedSubtitles(createdTracks)\n      else createdTracks.forEach((track) => track.revoke?.())\n    })\n    return () => {\n      active = false\n      createdTracks.forEach((track) => track.revoke?.())\n    }\n  }, [subtitleTracks])\n'''
if old_sub not in s: raise SystemExit('subtitle block not found')
s=s.replace(old_sub,new_sub)
# Add reset effect before autoStart effect
insert_before='''  useEffect(() => {\n    if (!autoStart) return\n'''
reset_effect='''  useEffect(() => {\n    attemptedRef.current.clear()\n    activeUrlRef.current = ''\n    startingRef.current = false\n    lastStreamSignatureRef.current = ''\n    setActiveStream(null)\n    setMutedFallback(false)\n    setStatus('searching')\n    cleanup()\n    const video = videoRef.current\n    if (video) {\n      try { video.removeAttribute('src') } catch {}\n      try { video.load() } catch {}\n    }\n  }, [playbackKey])\n\n'''
if insert_before not in s: raise SystemExit('autostart marker not found')
s=s.replace(insert_before, reset_effect+insert_before)
# Change chooseNext to prioritize list already ranked and skip weak matches only when better source exists
old_choose="const chooseNext = () => streams.find((stream) => stream?.url && !attemptedRef.current.has(stream.url)) || null"
new_choose="const chooseNext = () => {\n    const candidates = streams.filter((stream) => stream?.url && !attemptedRef.current.has(stream.url))\n    if (!candidates.length) return null\n    const confident = candidates.filter((stream) => (stream.matchScore ?? 1) >= 0.55)\n    return (confident.length ? confident : candidates)[0] || null\n  }"
if old_choose not in s: raise SystemExit('chooseNext not found')
s=s.replace(old_choose,new_choose)
# Replace non-HLS start logic with canplay promise / event
old_mp4='''      } else {\n        video.src = stream.url\n        video.preload = 'auto'\n        video.load()\n        startTimerRef.current = window.setTimeout(() => {\n          if (activeUrlRef.current === stream.url && video.readyState < 2) reportFailure(stream)\n        }, 15000)\n        await playVideo(stream, token)\n      }\n'''
new_mp4='''      } else {\n        video.src = stream.url\n        video.preload = 'auto'\n        video.load()\n        startTimerRef.current = window.setTimeout(() => {\n          if (activeUrlRef.current === stream.url && video.readyState < 2) reportFailure(stream)\n        }, 12000)\n\n        if (video.readyState >= 3) {\n          await playVideo(stream, token)\n        } else {\n          await new Promise((resolve, reject) => {\n            let settled = false\n            const finish = (fn) => {\n              if (settled) return\n              settled = true\n              video.removeEventListener('canplay', onCanPlay)\n              video.removeEventListener('error', onLoadError)\n              fn()\n            }\n            const onCanPlay = () => finish(resolve)\n            const onLoadError = () => finish(() => reject(new Error('Video Source Failed To Load.')))\n            video.addEventListener('canplay', onCanPlay, { once: true })\n            video.addEventListener('error', onLoadError, { once: true })\n          })\n          if (activeUrlRef.current === stream.url) await playVideo(stream, token)\n        }\n      }\n'''
if old_mp4 not in s: raise SystemExit('mp4 block not found')
s=s.replace(old_mp4,new_mp4)
# Change HLS buffer values for balance and error behavior
s=s.replace('''          maxBufferLength: 60,\n          maxMaxBufferLength: 180,\n          backBufferLength: 30,\n''','''          maxBufferLength: 45,\n          maxMaxBufferLength: 120,\n          backBufferLength: 20,\n          maxBufferHole: 0.5,\n''')
p.write_text(s)
